export function dashboard(team, period, sort, requestedPage) {
  // Fixed synthetic dataset
  const orders = [
    { id: 'N1', day: 1, team: 'North', minutes: 20, completed: true },
    { id: 'N2', day: 2, team: 'North', minutes: 40, completed: false },
    { id: 'N3', day: 2, team: 'North', minutes: 60, completed: true },
    { id: 'S1', day: 2, team: 'South', minutes: 10, completed: true },
    { id: 'S2', day: 3, team: 'South', minutes: 30, completed: false },
    { id: 'X1', day: 2, team: '', minutes: 15, completed: true },
    { id: 'X2', day: 2, team: 'North', minutes: -5, completed: true }
  ];

  const staffing = [
    { day: 1, team: 'North', hours: 4 },
    { day: 2, team: 'North', hours: 5 },
    { day: 2, team: 'South', hours: 3 }
  ];

  // Validate orders
  let excluded = 0;
  let validOrders = [];
  for (let order of orders) {
    if (!order.team || order.day < 1 || order.day > 3) {
      excluded++;
      continue;
    }
    if (order.minutes < 0) {
      excluded++;
      continue;
    }
    if (order.completed === true || order.completed === false) {
      validOrders.push(order);
    } else {
      excluded++;
      continue;
    }
  }

  const days = period === 'Jan 1–3' ? [1, 2, 3] : [Number(period.split(' ')[1])];
  const teams = team === 'All teams' ? ['North', 'South'] : [team];
  const filteredOrders = validOrders.filter(order => days.includes(order.day) && teams.includes(order.team));

  // Compute volume, rate, median
  let volume = filteredOrders.length;
  let durations = filteredOrders.map(order => order.minutes);
  let rate = null;
  let median = null;

  if (volume > 0) {
    rate = Math.round((filteredOrders.filter(order => order.completed).length / volume) * 100);
    if (volume % 2 === 0) {
      let sortedDurations = [...durations].sort((a, b) => a - b);
      let mid = volume / 2;
      median = (sortedDurations[mid - 1] + sortedDurations[mid]) / 2;
    } else {
      let sortedDurations = [...durations].sort((a, b) => a - b);
      median = sortedDurations[Math.floor(volume / 2)];
    }
  }

  const staffingRows = teams.map(name => {
    const entries = staffing.filter(row => row.team === name && days.includes(row.day));
    return {
      team: name,
      hours: entries.reduce((total, row) => total + row.hours, 0),
      completed: filteredOrders.filter(order => order.team === name && order.completed).length,
      incomplete: days.some(day => !entries.some(row => row.day === day))
    };
  });
  const daily = days.map(day => {
    const rows = filteredOrders.filter(order => order.day === day);
    return {day, volume: rows.length, rate: rows.length ? Math.round(rows.filter(order => order.completed).length / rows.length * 100) : null};
  });
  const allOrders = [...filteredOrders].sort(sort === 'Duration'
    ? (a, b) => a.minutes - b.minutes || a.id.localeCompare(b.id)
    : (a, b) => a.id.localeCompare(b.id));
  const pageSize = 5;
  const pages = Math.max(1, Math.ceil(allOrders.length / pageSize));
  const page = Math.max(1, Math.min(requestedPage, pages));
  const ordersForPage = allOrders.slice((page - 1) * pageSize, page * pageSize);
  return {volume, rate, median, excluded, orders: ordersForPage, allOrders, staffing: staffingRows, daily, page, pages};
}

import { dashboard } from './domain.js';

const byId = id => document.getElementById(id);
const controls = {team: byId('team'), period: byId('period'), sort: byId('sort')};
const storageKey = 'recursa-operations-view';
const state = {team: 'All teams', period: 'Jan 1–3', sort: 'ID', day: null, page: 1};
try {
  const saved = JSON.parse(localStorage.getItem(storageKey) || '{}');
  for (const [key, select] of Object.entries(controls)) {
    if ([...select.options].some(option => option.value === saved[key])) state[key] = saved[key];
  }
  if ([1, 2, 3].includes(saved.day)) state.day = saved.day;
} catch {
  byId('feedback').textContent = 'Saved view could not be restored.';
}
for (const [key, select] of Object.entries(controls)) {
  select.value = state[key];
  select.addEventListener('change', () => {
    state[key] = select.value;
    state.page = 1;
    if (key === 'period') state.day = null;
    render();
  });
}

function renderRows(tableId, rows) {
  const tbody = document.querySelector(`#${tableId} tbody`);
  tbody.replaceChildren();
  rows.forEach(row => {
    const tr = document.createElement('tr');
    row.forEach(cell => {
      const td = document.createElement('td');
      td.textContent = cell;
      tr.appendChild(td);
    });
    tbody.appendChild(tr);
  });
}

function orderCells(order) {
  return [order.id, 'Jan ' + order.day, order.team, order.minutes, order.completed ? 'Completed' : 'Open'];
}

let current;
function render() {
  const period = state.day === null ? state.period : 'Jan ' + state.day;
  current = dashboard(state.team, period, state.sort, state.page);
  state.page = current.page;
  byId('volume').textContent = 'Volume: ' + current.volume;
  byId('rate').textContent = 'Completion rate: ' + (current.rate === null ? '—' : current.rate + '%');
  byId('median').textContent = 'Median turnaround: ' + (current.median === null ? '—' : current.median + ' min');
  byId('excluded').textContent = 'Excluded records: ' + current.excluded;
  renderRows('staffing', current.staffing.map(row => [
    row.team, 'Staffing hours: ' + row.hours, 'Completed orders: ' + row.completed,
    row.incomplete ? 'Staffing data incomplete' : 'Complete coverage'
  ]));
  renderRows('orders', current.orders.map(orderCells));
  byId('page').textContent = 'Page ' + current.page + ' of ' + current.pages;
  byId('prev').disabled = current.page === 1;
  byId('next').disabled = current.page === current.pages;
  const daily = dashboard(state.team, state.period, state.sort, 1).daily;
  byId('daily').replaceChildren(...daily.map(row => {
    const button = document.createElement('button');
    button.type = 'button';
    button.setAttribute('aria-label', 'Jan ' + row.day);
    button.setAttribute('aria-pressed', String(state.day === row.day));
    const title = document.createElement('strong');
    title.textContent = 'Jan ' + row.day;
    const bar = document.createElement('meter');
    bar.max = 5;
    bar.value = row.volume;
    bar.setAttribute('aria-hidden', 'true');
    const count = document.createElement('span');
    count.textContent = row.volume + ' orders · ' + (row.rate === null ? '—' : row.rate + '% complete');
    button.append(title, bar, count);
    button.addEventListener('click', () => {
      state.day = state.day === row.day ? null : row.day;
      state.page = 1;
      render();
      byId('daily').querySelector('[aria-label="Jan ' + row.day + '"]')?.focus();
    });
    return button;
  }));
}

byId('prev').addEventListener('click', () => { state.page--; render(); });
byId('next').addEventListener('click', () => { state.page++; render(); });
byId('save').addEventListener('click', () => {
  localStorage.setItem(storageKey, JSON.stringify(state));
  byId('feedback').textContent = 'View saved.';
});
byId('export').addEventListener('click', () => {
  const escapeCell = cell => '"' + String(cell).replaceAll('"', '""') + '"';
  const rows = [['ID', 'Day', 'Team', 'Duration', 'Status'], ...current.allOrders.map(orderCells)];
  const csv = rows.map(row => row.map(escapeCell).join(',')).join(String.fromCharCode(13, 10));
  const blob = new Blob([csv], {type: 'text/csv;charset=utf-8'});
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = 'orders.csv';
  link.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
  byId('feedback').textContent = 'CSV exported.';
});
render();

